    44  extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    45  {
    46      const otPanId panId = 0xdead;
    47
    48      otInstance * instance = NULL;
    49      otRadioFrame frame;
    50      uint8_t *    buf = NULL;
    51
    52      VerifyOrExit(size <= OT_RADIO_FRAME_MAX_SIZE);
    53
    54      FuzzerPlatformInit();
    55
    56      instance = otInstanceInitSingle();
    57      otLinkSetPanId(instance, panId);
    58      otIp6SetEnabled(instance, true);
    59      otThreadSetEnabled(instance, true);
    60      otThreadBecomeLeader(instance);
    61
    62      buf = static_cast<uint8_t *>(malloc(size));
    63
    64      memset(&frame, 0, sizeof(frame));
    65      frame.mPsdu    = buf;
    66      frame.mChannel = 11;
    67      frame.mLength  = static_cast<uint8_t>(size);
    68
    69      memcpy(buf, data, frame.mLength);
    70
    71      otPlatRadioReceiveDone(instance, &frame, OT_ERROR_NONE);
    72
    73      while (otTaskletsArePending(instance))
    74      {
    75          otTaskletsProcess(instance);
    76      }
    77
    78  exit:
    79
    80      if (buf != NULL)
    81      {
    82          free(buf);
    83      }
    84
    85      if (instance != NULL)
    86      {
    87          otInstanceFinalize(instance);
    88      }
    89
    90      return 0;
    91  }
